403:    expect(v!.host?.node.projectionKey).toBe(FAC); // drawn by the facility the scene holds
404:    expect(v!.at()![0]).toBeCloseTo(100 + 40 * (20 / GEOMETRY.facilityR), 6); // where it sat in the station (scaled to its drawn size), from the station's place now
