484:    const jump = maneuvers.find((m) => m.title === 'Station jump-in')!.phase as Record<string, (c: unknown, m: unknown) => Call[]>;
486:    const m = planned(RULE.facilityEnter, 'e1', { facility: [WI1], agent: [A] });
