/** What the runner knows of an effect a command made: its name, weight, budget and clock. */
export interface RunMeta {
  name: string;
  weight: number;
  cuttable: boolean;
  /** Overrides the effect's own clock (a protect on the beat's clock, say). */
  clock?: 'travel' | 'accent';
}

